import os
wd = os.environ['TRAJECTORY_WORKDIR']
for root, dirs, files in os.walk(wd):
    # don't descend into memory
    dirs[:] = [d for d in dirs if d != 'memory']
    rel = os.path.relpath(root, wd)
    for f in files:
        p = os.path.join(root, f)
        try:
            sz = os.path.getsize(p)
        except OSError:
            sz = -1
        print(f"{rel}/{f}  ({sz} B)")
